//! The exports only Linux implements, declared on every platform.
//!
//! `index.js` and `index.d.ts` are generated by the Windows build and
//! committed, and CI fails when a Windows build would change them. So every
//! export exists on Windows too: these bodies call the Linux backend there and
//! report "Linux only" (or nothing) elsewhere. The app only calls them on
//! Linux. Keeping the declarations here, once, keeps their documentation the
//! same whichever platform generates the bindings.

use napi::bindgen_prelude::{AsyncTask, Buffer};
use napi::{Env, Task};
use napi_derive::napi;

#[cfg(target_os = "linux")]
use crate::capture::linux::{cursor_meta, input_clicks, picked};

#[cfg(not(target_os = "linux"))]
fn linux_only<T>(what: &str) -> napi::Result<T> {
  Err(napi::Error::from_reason(format!("{what} is only available on Linux")))
}

/// Linux only: one command on Hyprland's control socket, and its reply as text.
///
/// For the app's Hyprland IPC (click capture): a blocking round trip that
/// never leaves the compositor waiting on the caller's event loop.
#[napi]
pub fn hyprland_ipc(command: String) -> napi::Result<String> {
  #[cfg(target_os = "linux")]
  return crate::cursor::hyprland_command(&command).map_err(napi::Error::from_reason);
  #[cfg(not(target_os = "linux"))]
  {
    let _ = command;
    linux_only("Hyprland IPC")
  }
}

/// Linux only: what the user picked in the portal, for the recorder's source tile.
#[napi(object)]
pub struct PickedScreenSource {
  /// "screen", "window", or "unknown" when the portal does not say.
  pub kind: String,
  pub width: Option<u32>,
  pub height: Option<u32>,
  /// A JPEG of the source's first frame, when one arrived in time.
  pub thumbnail_jpeg: Option<Buffer>,
}

pub struct PickScreenSource;

impl Task for PickScreenSource {
  type Output = (String, Option<(u32, u32)>, Option<Vec<u8>>);
  type JsValue = PickedScreenSource;

  fn compute(&mut self) -> napi::Result<Self::Output> {
    #[cfg(target_os = "linux")]
    return picked::pick()
      .map(|picked| (picked.kind.to_string(), picked.size, picked.thumbnail))
      .map_err(napi::Error::from_reason);
    #[cfg(not(target_os = "linux"))]
    linux_only("The screen picker")
  }

  fn resolve(&mut self, _env: Env, (kind, size, thumbnail): Self::Output) -> napi::Result<PickedScreenSource> {
    Ok(PickedScreenSource {
      kind,
      width: size.map(|(width, _)| width),
      height: size.map(|(_, height)| height),
      thumbnail_jpeg: thumbnail.map(Buffer::from),
    })
  }
}

/// Linux only: show the portal's screen and window picker now, and hold the
/// choice for the next recording. Rejects with "screen selection was
/// cancelled" when the user closes the picker.
#[napi(ts_return_type = "Promise<PickedScreenSource>")]
pub fn pick_screen_source() -> AsyncTask<PickScreenSource> {
  AsyncTask::new(PickScreenSource)
}

/// Linux only: let go of a picked source that no recording took.
#[napi]
pub fn release_screen_source() {
  #[cfg(target_os = "linux")]
  picked::release();
}

/// Linux only: where the pointer is in the frame being recorded.
#[napi(object)]
pub struct ScreenCursorPosition {
  /// 0 at the frame's left edge, 1 at its right; outside that when off it.
  pub x: f64,
  /// 0 at the frame's top edge, 1 at its bottom; outside that when off it.
  pub y: f64,
}

/// Linux only: the pointer's position in the screen recording that is
/// running, as the desktop reported it alongside the frames. `null` when no
/// recording gets cursor metadata (as under Hyprland, whose position comes
/// from its own socket) or no position has arrived yet.
#[napi]
pub fn screen_cursor_position() -> Option<ScreenCursorPosition> {
  #[cfg(target_os = "linux")]
  return cursor_meta::active_position().map(|point| ScreenCursorPosition { x: point.x, y: point.y });
  #[cfg(not(target_os = "linux"))]
  None
}

/// Linux only: whether recso can see mouse and touchpad clicks.
#[napi(object)]
pub struct InputClickAccess {
  /// Mice and touchpads found.
  pub devices: u32,
  /// How many of them recso may read. Zero with devices found means the user
  /// is not in the `input` group, or joined it without logging in again.
  pub readable: u32,
}

/// Linux only: a button press seen by `startInputClickCapture`.
#[napi(object)]
pub struct InputClick {
  /// "left", "right" or "middle".
  pub button: String,
  /// Wall-clock time, ms since the Unix epoch.
  pub at_epoch_ms: f64,
  /// The pointer as a fraction of the recorded frame, when available.
  pub x: Option<f64>,
  /// The pointer as a fraction of the recorded frame, when available.
  pub y: Option<f64>,
}

#[cfg(target_os = "linux")]
fn to_access((devices, readable): (u32, u32)) -> InputClickAccess {
  InputClickAccess { devices, readable }
}

/// Linux only: check how many mouse and touchpad devices recso can read now.
/// Each opened device is closed again; this does not start capture.
#[napi]
pub fn input_click_access() -> InputClickAccess {
  #[cfg(target_os = "linux")]
  return to_access(input_clicks::access());
  #[cfg(not(target_os = "linux"))]
  InputClickAccess { devices: 0, readable: 0 }
}

/// Linux only: stop any running capture, then read clicks from accessible
/// mouse and touchpad devices on a background thread.
#[napi]
pub fn start_input_click_capture() -> InputClickAccess {
  #[cfg(target_os = "linux")]
  return to_access(input_clicks::start());
  #[cfg(not(target_os = "linux"))]
  InputClickAccess { devices: 0, readable: 0 }
}

/// Linux only: take clicks seen since the last call, oldest first.
#[napi]
pub fn drain_input_clicks() -> Vec<InputClick> {
  #[cfg(target_os = "linux")]
  return input_clicks::drain()
    .into_iter()
    .map(|click| InputClick {
      button: click.button.to_string(),
      at_epoch_ms: click.at_epoch_ms,
      x: click.position.map(|point| point.x),
      y: click.position.map(|point| point.y),
    })
    .collect();
  #[cfg(not(target_os = "linux"))]
  Vec::new()
}

/// Linux only: stop reading clicks, close devices, and clear pending clicks.
#[napi]
pub fn stop_input_click_capture() {
  #[cfg(target_os = "linux")]
  input_clicks::stop();
}
